@Test(arguments: golden.indices)
func connectingOrbMatchesGolden(_ index: Int) {
    let g = golden[index]
    let frame = OrbWeb.frame(size: 20, t: g.t)
    let dots = frame.dots.flatMap { [$0.x, $0.y, $0.z, $0.r, $0.white, $0.a] }
    let lines = frame.lines.flatMap { [$0.x1, $0.y1, $0.x2, $0.y2, $0.white, $0.a, $0.w] }
    #expect(dots.count == g.dots.count)
    #expect(lines.count == g.lines.count)
    for (got, want) in zip(dots + lines, g.dots + g.lines) {
        #expect(abs(got - want) < 0.0001, "t=\(g.t): got \(got), want \(want)")
    }
}
